// Get webhook payload
const payload = $('Webhook1').first().json.body || $('Webhook1').first().json;
const retryCount = payload.retryCount || 0;

// RETRY PATH: skip filtering, pass current slot directly
if (retryCount > 0) {
  console.log(`RETRY attempt #${retryCount} for slot: ${payload.currentSlot}`);
  return [{
    json: {
      ...payload,
      freshSlots: [payload.currentSlot],
      isRetry: true,
      retryCount
    }
  }];
}

// NORMAL PATH: filter slots against blacklist
const blacklistedSlots = $input.all().map(r => r.json.slotValue).filter(Boolean);
const foundSlots = payload.foundSlots || [];
const freshSlots = foundSlots.filter(s => !blacklistedSlots.includes(s));

console.log(`Slots received: ${foundSlots.length} | Blacklisted: ${blacklistedSlots.length} | Fresh: ${freshSlots.length}`);

return [{
  json: {
    ...payload,
    freshSlots,
    isRetry: false,
    retryCount: 0
  }
}];

// Explode freshSlots into one item per slot for bulk insert
const data = $input.first().json;
const freshSlots = data.freshSlots || [];
const now = new Date().toISOString();

return freshSlots.map(slot => ({
  json: {
    slotValue: slot,
    weekLabel: data.weekLabel || '',
    office: data.Office || 'KAIRO',
    calendarId: String(data.CalendarId || '44281520'),
    detectedAt: now,
    status: 'PENDING',
    assignedToStudentId: null,
    attemptedAt: null,
    result: '',
    _payload: data
  }
}));

// The insert node returns DB rows, not our original data
// So we reach back to Prepare Slots for Insert to get _payload
const allItems = $('Prepare Slots for Insert').all();
if (!allItems.length) return [];

// All items share the same _payload — grab from first
const payload = allItems[0].json._payload;
if (!payload) throw new Error('_payload missing from Prepare Slots for Insert');

console.log(`Rebuilt payload with ${payload.freshSlots ? payload.freshSlots.length : 0} fresh slots`);
return [{ json: { ...payload } }];

// Split freshSlots into one item per slot for sequential processing
const data = $input.first().json;
const freshSlots = data.freshSlots || [];

return freshSlots.map((slot, index) => ({
  json: {
    ...data,
    currentSlot: slot,
    slotIndex: index
  }
}));

// Merge student data with current slot + session data
const student = $('Get Next PENDING Student').first().json;
const slotData = $('One Slot at a Time').first().json;

console.log(`Processing: Student ${student.Firstname} ${student.Lastname} | Slot: ${slotData.currentSlot}`);

return [{
  json: {
    ...slotData,
    student
  }
}];

// Extract fresh CAPTCHA/session fields from booking form HTML on EVERY attempt
const response = $input.first().json;
const html = response.body || response.data || '';
const merged = $('Merge Student + Slot').first().json;

if (!html || !html.includes('BDC_VCID_Captcha')) {
  throw new Error(`Booking form/captcha not found. HTML snippet: ${String(html).slice(0, 500)}`);
}

const pick = (re) => {
  const m = html.match(re);
  return m ? m[1] : null;
};

const BDC_VCID = pick(/name="BDC_VCID_Captcha"[^>]*value="([^"]+)"/i);
const BDC_Hs = pick(/name="BDC_Hs_Captcha"[^>]*value="([^"]+)"/i) || '';
const BDC_SP = pick(/name="BDC_SP_Captcha"[^>]*value="([^"]+)"/i) || '';
const BDC_BW = pick(/name="BDC_BackWorkaround_Captcha"[^>]*value="([^"]+)"/i) || '0';
const token = pick(/id="Token"[^>]*value="([^"]+)"/i) || merged.token;
const startTime = pick(/id="StartTime"[^>]*value="([^"]+)"/i) || merged.currentSlot;

const action = pick(/<form[^>]*action="([^"]+)"/i);
const bookingEndpoint = action
  ? `https://appointment.bmeia.gv.at${action}`
  : (merged.bookingEndpoint || 'https://appointment.bmeia.gv.at/HomeWeb/Appointment');

if (!BDC_VCID || !token || !bookingEndpoint) {
  throw new Error(`Missing fresh fields: vcid=${!!BDC_VCID}, token=${!!token}, endpoint=${!!bookingEndpoint}`);
}

const captchaImageUrl = `https://appointment.bmeia.gv.at/BotDetectCaptcha.ashx?get=image&c=Captcha&t=${BDC_VCID}`;

console.log(`Fresh CAPTCHA synced | vcid=${BDC_VCID} | endpoint=${bookingEndpoint}`);

return [{
  json: {
    ...merged,
    BDC_VCID_Captcha: BDC_VCID,
    BDC_Hs_Captcha: BDC_Hs,
    BDC_SP_Captcha: BDC_SP,
    BDC_BackWorkaround_Captcha: BDC_BW,
    token,
    startTime,
    captchaImageUrl,
    bookingEndpoint,
    bookingFormHtml: html
  }
}];

// Extract CAPTCHA text and build a strictly synced booking payload
const geminiResponse = $input.first().json;
const formData = $('Extract Fresh CAPTCHA').first().json;
const student = formData.student;

// Extract text from Gemini response shape
let captchaText = '';
if (geminiResponse.content?.parts?.[0]?.text) {
  captchaText = geminiResponse.content.parts[0].text;
} else if (geminiResponse.text) {
  captchaText = geminiResponse.text;
} else if (typeof geminiResponse === 'string') {
  captchaText = geminiResponse;
}

// Normalize CAPTCHA aggressively to avoid visual/style mismatch
captchaText = String(captchaText).trim().toUpperCase();

if (!formData.BDC_VCID_Captcha || !formData.token || !formData.bookingEndpoint) {
  throw new Error('Missing fresh captcha/session fields before submit');
}
if (!captchaText || captchaText.length < 4) {
  throw new Error(`Invalid captchaText: "${captchaText}"`);
}

// Normalize and validate Sex (must be 1/2/3/4; 0 is invalid)
const rawSex = student.Sex;
const sexMap = {
  male: '1',
  female: '2',
  unknown: '3',
  'not applicable': '4',
  notapplicable: '4',
  m: '1',
  f: '2'
};

let sexValue = String(rawSex ?? '').trim().toLowerCase();
if (sexMap[sexValue]) sexValue = sexMap[sexValue];
if (/^\d+$/.test(sexValue)) sexValue = String(parseInt(sexValue, 10));
if (!['1', '2', '3', '4'].includes(sexValue)) {
  throw new Error(`Invalid Sex value for applicant "${student.Firstname} ${student.Lastname}": "${rawSex}"`);
}

console.log({
  endpoint: formData.bookingEndpoint,
  vcid: formData.BDC_VCID_Captcha,
  hs8: String(formData.BDC_Hs_Captcha || '').slice(0, 8),
  sp: formData.BDC_SP_Captcha,
  bw: formData.BDC_BackWorkaround_Captcha,
  token12: String(formData.token || '').slice(-12),
  captchaText
});

return [{
  json: {
    ...formData,
    captchaText,
    bookingBody: {
      Office: formData.Office,
      Language: formData.Language,
      CalendarId: String(formData.CalendarId),
      Token: formData.token,
      PersonCount: '1',
      StartTime: formData.startTime,
      Lastname: student.Lastname,
      Firstname: student.Firstname,
      DateOfBirth: student.DateOfBirth,
      TraveldocumentNumber: student.TraveldocumentNumber,
      Sex: sexValue,
      Street: student.Street,
      Postcode: String(student.Postcode),
      City: student.City,
      Country: String(student.Country),
      Telephone: student.Telephone,
      Email: student.Email,
      LastnameAtBirth: student.LastnameAtBirth,
      NationalityAtBirth: String(student.NationalityAtBirth),
      CountryOfBirth: String(student.CountryOfBirth),
      PlaceOfBirth: student.PlaceOfBirth,
      NationalityForApplication: String(student.NationalityForApplication),
      TraveldocumentDateOfIssue: student.TraveldocumentDateOfIssue,
      TraveldocumentValidUntil: student.TraveldocumentValidUntil,
      TraveldocumentIssuingAuthority: String(student.TraveldocumentIssuingAuthority),
      BDC_VCID_Captcha: formData.BDC_VCID_Captcha,
      BDC_BackWorkaround_Captcha: String(formData.BDC_BackWorkaround_Captcha),
      BDC_Hs_Captcha: formData.BDC_Hs_Captcha,
      BDC_SP_Captcha: String(formData.BDC_SP_Captcha),
      CaptchaText: captchaText
    }
  }
}];

// Detect booking result from HTML response
const response = $input.first().json;
const html = response.body || response.data || '';
const prevData = $('Build Booking Body').first().json;

// PRIMARY DETECTION: page title
// Success = confirmation page (title no longer says 'Capture data')
// Fail = form returned with same title
const isCapturePage = html.includes('Capture data') || html.includes('Austrian appointment system - Capture');

let resultType = 'OTHER_FAIL';
let errorText = '';

if (!isCapturePage) {
  resultType = 'SUCCESS';
} else if (html.includes('no appointments available') || html.includes('keine Termine')) {
  resultType = 'SLOT_TAKEN';
  errorText = 'Slot was taken by another user';
} else if (html.includes('validation-summary-errors') || html.includes('field-validation-error')) {
  // Extract error text
  const errMatch = html.match(/class="field-validation-error"[^>]*>([^<]+)</);
  errorText = errMatch ? errMatch[1].trim() : 'Validation error';
  resultType = 'OTHER_FAIL';
} else if (html.includes('BDC_VCID_Captcha')) {
  // Form returned with new CAPTCHA — CAPTCHA was wrong
  resultType = 'CAPTCHA_FAIL';
  errorText = 'CAPTCHA answer incorrect';
}

console.log(`Result: ${resultType} | ${errorText}`);

// If CAPTCHA fail, extract fresh CAPTCHA fields from returned HTML
let freshCaptchaFields = {};
if (resultType === 'CAPTCHA_FAIL') {
  const vcidMatch = html.match(/name="BDC_VCID_Captcha"[^>]+value="([^"]+)"/);
  const hsMatch = html.match(/name="BDC_Hs_Captcha"[^>]+value="([^"]+)"/);
  const spMatch = html.match(/name="BDC_SP_Captcha"[^>]+value="([^"]+)"/);
  const bwMatch = html.match(/name="BDC_BackWorkaround_Captcha"[^>]+value="([^"]+)"/);
  const tokenMatch = html.match(/id="Token"[^>]+value="([^"]+)"/);
  const newVCID = vcidMatch ? vcidMatch[1] : null;
  freshCaptchaFields = {
    BDC_VCID_Captcha: newVCID,
    BDC_Hs_Captcha: hsMatch ? hsMatch[1] : '',
    BDC_SP_Captcha: spMatch ? spMatch[1] : '',
    BDC_BackWorkaround_Captcha: bwMatch ? bwMatch[1] : '0',
    token: tokenMatch ? tokenMatch[1] : prevData.token,
    captchaImageUrl: newVCID
      ? `https://appointment.bmeia.gv.at/BotDetectCaptcha.ashx?get=image&c=Captcha&t=${newVCID}`
      : prevData.captchaImageUrl
  };
}

return [{
  json: {
    ...prevData,
    resultType,
    errorText,
    freshCaptchaFields,
    responseSnippet: html.substring(0, 800)
  }
}];

