// Handle CAPTCHA retry logic
const data = $input.first().json;
const retryCount = (data.retryCount || 0) + 1;

console.log(`CAPTCHA retry ${retryCount}/3`);

if (retryCount > 3) {
  return [{ json: { ...data, retryCount, giveUp: true } }];
}

// Prepare retry payload with fresh CAPTCHA fields already extracted
const fresh = data.freshCaptchaFields || {};
return [{
  json: {
    ...data,
    ...fresh,
    retryCount,
    giveUp: false,
    isRetry: true,
    currentSlot: data.currentSlot
  }
}];

